CEID = {101: "TRACK_IN", 102: "TRACK_OUT", 900: "ALARM"}

def handle(eqp, ceid, v):
    ev = CEID.get(ceid)
    if ev is None:
        return f"IGNORE ceid={ceid}"
    if ev == "TRACK_IN":
        return f"MES.trackIn(lot={v['LOTID']}, eqp={eqp})"
    if ev == "TRACK_OUT":
        return f"MES.trackOut(lot={v['LOTID']}, eqp={eqp})"
    return f"MES.holdEqp(eqp={eqp}, alarm={v['ALID']})"

print(handle("ETCH07", 101, {"LOTID": "L001"}))  # MES.trackIn(lot=L001, eqp=ETCH07)
print(handle("ETCH07", 900, {"ALID": "2301"}))   # MES.holdEqp(eqp=ETCH07, alarm=2301)
print(handle("ETCH07", 555, {}))                  # IGNORE ceid=555
